/* ================================================================== */
/* Top-level function dispatch                                        */
/* ================================================================== */

static inline void
npt_dispatch_toplevel(struct npt_dispatch_context *ctx,
                      uint32_t group, uint32_t func_id,
                      uint32_t cmd_flags)
{
    switch (group) {
    case 1:
        switch (func_id) {
        case 0:
            npt_dispatch_CreateDXGIFactory(ctx, cmd_flags);
            break;
        case 1:
            npt_dispatch_CreateDXGIFactory1(ctx, cmd_flags);
            break;
        case 2:
            npt_dispatch_CreateDXGIFactory2(ctx, cmd_flags);
            break;
        case 3:
            npt_dispatch_DXGIDeclareAdapterRemovalSupport(ctx, cmd_flags);
            break;
        default:
            npt_cs_decoder_set_fatal(ctx->decoder);
            break;
        }
        break;
    case 2:
        switch (func_id) {
        case 0:
            npt_dispatch_D3D11CreateDevice(ctx, cmd_flags);
            break;
        case 1:
            npt_dispatch_D3D11CreateDeviceAndSwapChain(ctx, cmd_flags);
            break;
        case 2:
            npt_dispatch_D3D11On12CreateDevice(ctx, cmd_flags);
            break;
        default:
            npt_cs_decoder_set_fatal(ctx->decoder);
            break;
        }
        break;
    case 3:
        switch (func_id) {
        case 0:
            npt_dispatch_D3D12CreateDevice(ctx, cmd_flags);
            break;
        case 1:
            npt_dispatch_D3D12CreateRootSignatureDeserializer(ctx, cmd_flags);
            break;
        case 2:
            npt_dispatch_D3D12CreateVersionedRootSignatureDeserializer(ctx, cmd_flags);
            break;
        case 3:
            npt_dispatch_D3D12SerializeRootSignature(ctx, cmd_flags);
            break;
        case 4:
            npt_dispatch_D3D12SerializeVersionedRootSignature(ctx, cmd_flags);
            break;
        default:
            npt_cs_decoder_set_fatal(ctx->decoder);
            break;
        }
        break;
    default:
        npt_cs_decoder_set_fatal(ctx->decoder);
        break;
    }
}

/* ================================================================== */
/* Main dispatch entry point                                           */
/* ================================================================== */

static inline void
npt_dispatch_command(struct npt_dispatch_context *ctx)
{
    struct npt_command_header _hdr;
    npt_cs_decoder_read(ctx->decoder, sizeof(_hdr), &_hdr, sizeof(_hdr));

    const uint32_t _group = (_hdr.cmd_type >> 24) & 0xFF;

    if (_group == 255) {
        /* COM call: interface_id and method_index come straight from
         * cmd_type (no per-call GUID on the wire; pinned interface IDs
         * live in neptune-protocol/npt_interface_ids.json). */
        const uint16_t _interface_id = (_hdr.cmd_type >> 8) & 0xFFFFu;
        const uint8_t _method_index = _hdr.cmd_type & 0xFFu;
        npt_dispatch_com_call(ctx, _interface_id, _method_index,
                              _hdr.cmd_flags, _hdr.object_id);
    } else if (_group >= 1 && _group <= 3) {
        const uint32_t _func_id = _hdr.cmd_type & 0x00FFFFFF;
        npt_dispatch_toplevel(ctx, _group, _func_id, _hdr.cmd_flags);
    } else {
        npt_cs_decoder_set_fatal(ctx->decoder);
    }

    if (npt_cs_decoder_get_fatal(ctx->decoder))
        npt_log("dispatch error for cmd_type=0x%08x", _hdr.cmd_type);
}

